  if (!(bytes instanceof Uint8Array)) {
    throw new StoreError('BAD_INPUT', 'bytes must be a Uint8Array');
  }
  const table = crcTable();
  let crc = 0xffffffff;
  for (let i = 0; i < bytes.length; i += 1) {
    crc = table[(crc ^ bytes[i]) & 0xff] ^ (crc >>> 8);
  }
  return (crc ^ 0xffffffff) >>> 0;
}

