export function decodeLog(bytes) {
  if (!(bytes instanceof Uint8Array)) {
    throw new StoreError('BAD_INPUT', 'bytes must be a Uint8Array');
  }
  const records = [];
  let offset = 0;
  let truncated = false;
  const decoder = new TextDecoder();
  while (true) {
    if (bytes.length - offset < HEADER_BYTES) {
      truncated = offset < bytes.length;
      break;
    }
    const view = new DataView(bytes.buffer, bytes.byteOffset + offset, HEADER_BYTES);
    const length = view.getUint32(0, false);
    const checksum = view.getUint32(4, false);
    if (bytes.length - offset - HEADER_BYTES < length) {
      truncated = true;
      break;
    }
    const payload = bytes.subarray(offset + HEADER_BYTES, offset + HEADER_BYTES + length);
    if (crc32(payload) !== checksum) {
      truncated = true;
      break;
    }
    let parsed;
    try {
      parsed = JSON.parse(decoder.decode(payload));
    } catch {
      truncated = true;
      break;
    }
    if (!isRecord(parsed)) {
      truncated = true;
      break;
    }
    records.push(parsed);
    offset += HEADER_BYTES + length;
  }
  return { records, bytesUsed: offset, truncated };
}

