{"file_path":"src/store.js","content":"/**
 * A key-value store whose only durable form is an append-only log.
 */
import { StoreError, encodeRecord, decodeLog } from './log.js';

/**
 * Reject keys that cannot be logged.
 *
 * @param {unknown} key Candidate key.
 * @returns {string} The validated key.
 */
function checkKey(key) {
  if (typeof key !== 'string' || key === '') {
    throw new StoreError('BAD_KEY', 'key must be a non-empty string');
  }
  return key;
}

/**
 * Deep-clone a value while validating that it is losslessly JSON-representable.
 *
 * @param {unknown} value Candidate value.
 * @param {Set<unknown>} seen Ancestor objects, to detect cycles.
 * @returns {unknown} A deep clone of value.
 */
function cloneValue(value, seen) {
  if (value === null) return null;
  if (typeof value === 'string' || typeof value === 'boolean') return value;
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) {
      throw new StoreError('BAD_VALUE', 'value is not serializable');
    }
    return value;
  }
  if (Array.isArray(value)) {
    if (seen.has(value)) {
      throw new StoreError('BAD_VALUE', 'value is not serializable');
    }
    seen.add(value);
    const result = value.map((item) => cloneValue(item, seen));
    seen.delete(value);
    return result;
  }
  if (typeof value === 'object') {
    const proto = Object.getPrototypeOf(value);
    if (proto !== Object.prototype && proto !== null) {
      throw new StoreError('BAD_VALUE', 'value is not serializable');
    }
    if (seen.has(value)) {
      throw new StoreError('BAD_VALUE', 'value is not serializable');
    }
    seen.add(value);
    const result = {};
    for (const key of Object.keys(value)) {
      const item = value[key];
      if (item === undefined) {
        throw new StoreError('BAD_VALUE', 'value is not serializable');
      }
      result[key] = cloneValue(item, seen);
    }
    seen.delete(value);
    return result;
  }
  throw new StoreError('BAD_VALUE', 'value is not serializable');
}

/**
 * Validate and deep-clone a value for storage.
 *
 * @param {unknown} value Candidate value.
 * @returns {unknown} A deep clone of value.
 */
function checkValue(value) {
  return cloneValue(value, new Set());
}

/** Key-value store backed by an in-memory append-only log. */
export class KvStore {
  #map = new Map();
  #chunks = [];
  #logLength = 0;

  /**
   * Append a framed record's bytes to the log.
   *
   * @param {{t: string, k: string, v?: unknown}} record Record to append.
   */
  #appendRecord(record) {
    const frame = encodeRecord(record);
    this.#chunks.push(frame);
    this.#logLength += frame.length;
  }

  /**
   * Store a value, appending a record to the log.
   *
   * @param {string} key Non-empty key.
   * @param {unknown} value Any JSON-representable value.
   * @returns {KvStore} This store, for chaining.
   */
  put(key, value) {
    const validKey = checkKey(key);
    const validValue = checkValue(value);
    this.#appendRecord({ t: 'put', k: validKey, v: validValue });
    this.#map.set(validKey, validValue);
    return this;
  }

  /**
   * Remove a key, appending a record only when the key is present.
   *
   * @param {string} key Non-empty key.
   * @returns {boolean} True when the key existed.
   */
  delete(key) {
    const validKey = checkKey(key);
    const existed = this.#map.delete(validKey);
    if (existed) {
      this.#appendRecord({ t: 'del', k: validKey });
    }
    return existed;
  }

  /**
   * Read a value.
   *
   * @param {string} key Non-empty key.
   * @returns {unknown} A copy of the stored value, or undefined.
   */
  get(key) {
    const validKey = checkKey(key);
    if (!this.#map.has(validKey)) return undefined;
    return cloneValue(this.#map.get(validKey), new Set());
  }

  /**
   * Test for a key.
   *
   * @param {string} key Non-empty key.
   * @returns {boolean} True when the key is present.
   */
  has(key) {
    return this.#map.has(checkKey(key));
  }

  /** @returns {number} Number of live keys. */
  get size() {
    return this.#map.size;
  }

  /** @returns {string[]} Live keys in ascending order. */
  keys() {
    return [...this.#map.keys()].sort();
  }

  /** @returns {Array<[string, unknown]>} Live entries in ascending key order. */
  entries() {
    return this.keys().map((key) => [key, cloneValue(this.#map.get(key), new Set())]);
  }

  /** @returns {Uint8Array} A copy of the current log. */
  get log() {
    const result = new Uint8Array(this.#logLength);
    let offset = 0;
    for (const chunk of this.#chunks) {
      result.set(chunk, offset);
      offset += chunk.length;
    }
    return result;
  }

  /** @returns {{records: number, liveKeys: number, deadRecords: number}} Log occupancy. */
  stats() {
    const records = this.#chunks.length;
    const liveKeys = this.#map.size;
    return { records, liveKeys, deadRecords: records - liveKeys };
  }

  /**
   * Rewrite the log as one put per live key in ascending key order.
   *
   * @returns {{before: number, after: number, reclaimed: number}} Byte counts.
   */
  compact() {
    const before = this.#logLength;
    const newChunks = [];
    let newLength = 0;
    for (const key of this.keys()) {
      const frame = encodeRecord({ t: 'put', k: key, v: cloneValue(this.#map.get(key), new Set()) });
      newChunks.push(frame);
      newLength += frame.length;
    }
    this.#chunks = newChunks;
    this.#logLength = newLength;
    const after = this.#logLength;
    return { before, after, reclaimed: before - after };
  }

  /** @returns {{version: number, entries: Array<[string, unknown]>}} Portable snapshot. */
  snapshot() {
    return { version: 1, entries: this.entries() };
